// Copied verbatim from collabrium-dls/components.css lines 3002–3078 and 4204–4294, for side-by-side comparison only.
export const legacyDropdownCss = "/* Dropdown \u2014 Single select trigger. The box itself is Input Field's own\n   container \u2014 .c-field/.input-wrap/.icon-trailing/.c-field-error/\n   :disabled below are all reused verbatim, unmodified, the same way\n   Multiple select's own trigger reuses them; nothing here duplicates\n   that recipe. .c-dropdown-field only adds a Style axis Input Field\n   doesn't have (scoped to this class so bare .c-field \u2014 Input field,\n   Textarea, Password field, Search input \u2014 is untouched), plus the\n   dropdown-specific chevron/panel/open/has-value mechanics. Supersedes\n   an earlier draft that gave Single select its own Button-Secondary-\n   styled, radius-md trigger instead of reusing Input Field \u2014 that\n   recipe is gone; both Dropdown variants are Input-Field-based now. */\n.c-dropdown-field .input-wrap{cursor:pointer;}\n.c-dropdown-input{cursor:pointer; caret-color:transparent;}\n.c-dropdown-input::placeholder{color:var(--color-neutral-5);}\n.c-dropdown-chevron{transition:transform var(--duration-fast) var(--ease-standard);}\n\n/* Style \u2014 Outlined is Input Field's own default recipe above (no\n   modifier class). Border stays 1px at rest, colour only, in every\n   Style \u2014 the same compensation-free trick Multiple select's own\n   Style axis uses, so Open's 1px\u21922px Obsidian swap below needs no\n   per-style exception. Hover is a real :hover so a wired-up trigger\n   genuinely responds to the mouse; the .hover class exists only so a\n   static gallery card can depict the same look without real mouse\n   state. */\n.c-dropdown-field:hover input, .c-dropdown-field.hover input{background:var(--color-neutral-2);}\n\n/* Style \u2014 Borderless: transparent fill, no border \u2014 for inline\n   placements (toolbars, table headers) that shouldn't read as a boxed\n   field. */\n.c-dropdown-field.style-borderless input{background:transparent; border-color:transparent;}\n.c-dropdown-field.style-borderless:hover input, .c-dropdown-field.style-borderless.hover input{background:var(--color-neutral-2);}\n\n/* Explicit :focus/:disabled/.c-field-error overrides for Borderless \u2014\n   without these, a real focus/disabled/error event and the plain\n   .style-borderless rule above have equal specificity, and source\n   order alone would decide which wins; this makes the win deliberate\n   rather than incidental. Error reusing .c-field-error is the same\n   recipe Input Field's own Error state uses \u2014 not a bespoke\n   error-text element. */\n.c-dropdown-field.style-borderless input:focus{border-color:var(--color-obsidian);}\n.c-dropdown-field.style-borderless input:disabled{background:var(--color-neutral-2); border-color:transparent;}\n.c-dropdown-field.style-borderless.c-field-error input{border-color:var(--color-red);}\n\n/* States \u2014 layer on top of whichever Style is active above. Focus and\n   Disabled/Error come free from Input Field's own :focus/:disabled/\n   .c-field-error (inherited, not redeclared); .open/.has-value/\n   .read-only below are what Input Field doesn't have. */\n.c-dropdown-field.open input{border:2px solid var(--color-obsidian); padding:0 11px;}\n.c-dropdown-field.open .c-dropdown-chevron{transform:rotate(180deg);}\n.c-dropdown-field.has-value input{border-color:var(--color-obsidian);}\n.c-dropdown-field.read-only .input-wrap{pointer-events:none;}\n.c-dropdown-field.read-only .icon-trailing{display:none;}\n/* Borderless stays borderless through every State \u2014 Open and Filled's\n   border-color swap above is deliberately suppressed here so this\n   Style never shows a solid border, the one thing \"Borderless\" is\n   supposed to guarantee. Only overrides border-color (not the whole\n   border shorthand), so the width/padding compensation math above\n   still runs identically in every Style \u2014 there's just nothing visible\n   riding on it in this one. */\n.c-dropdown-field.style-borderless.open input, .c-dropdown-field.style-borderless.has-value input{border-color:transparent;}\n\n/* Panel \u2014 width:100% of the same .c-dropdown parent the trigger fills,\n   so the panel always matches the trigger's rendered width exactly in\n   every Style variant; min-width is a floor for narrow fields only,\n   never a reason for the panel to run narrower than the trigger. */\n.c-dropdown-panel{position:static; margin-top:var(--spacing-8); width:100%; background:var(--color-neutral-1); border:1px solid var(--color-neutral-3); border-radius:var(--radius-md); box-shadow:var(--shadow-3); overflow:hidden;}\n.c-dropdown-list{max-height:320px; overflow-y:auto; padding:var(--spacing-8) 0;}\n\n/* Dropdown Option \u2014 the row sub-component inside Single select's panel */\n.c-dropdown-row{display:flex; align-items:center; justify-content:space-between; gap:var(--spacing-8); padding:var(--spacing-8) var(--spacing-12); cursor:pointer;}\n.c-dropdown-row:hover, .c-dropdown-row.hover{background:var(--color-neutral-2);}\n.c-dropdown-row.selected{background:var(--color-neutral-2);}\n.c-dropdown-row.disabled{color:var(--color-neutral-4); cursor:not-allowed; pointer-events:none;}\n.c-dropdown-row-label{font-family:var(--font-primary); font-size:var(--text-body2-size); font-weight:var(--text-body2-weight); color:var(--color-neutral-9);}\n.c-dropdown-row.disabled .c-dropdown-row-label{color:var(--color-neutral-4);}\n.c-dropdown-row-check{flex:none; font-size:var(--icon-sm); color:var(--color-obsidian); visibility:hidden;}\n.c-dropdown-row.selected .c-dropdown-row-check{visibility:visible;}\n\n.c-dropdown-row-media,\n.c-dropdown-option-media{flex:none; display:flex; align-items:center; justify-content:center; width:20px; font-size:var(--icon-base); color:var(--color-neutral-5);}\n/* Search input's own 32px avatar recipe, scaled to the row's 24px and\n   reused rather than re-derived. font-style reset because it's a text\n   avatar sitting in an <i>, not an icon \u2014 the same reset Card's own\n   Profile card avatar needs for the same reason. */\n.c-dropdown-row-media.is-avatar,\n.c-dropdown-option-media.is-avatar{width:24px; height:24px; border-radius:var(--radius-pill); background:var(--color-neutral-2); color:var(--color-neutral-9); font-family:var(--font-primary); font-size:var(--text-label3-size); font-weight:700; font-style:normal;}\n/* With a leading media slot the row has three children, and .c-dropdown-row's\n   own justify-content:space-between would strand the label in the middle.\n   The label takes the free space instead \u2014 which changes nothing for a\n   plain two-child row, where space-between was already doing that job. */\n.c-dropdown-row > .c-dropdown-row-label,\n.c-dropdown-option > .c-dropdown-option-label{flex:1 1 auto; min-width:0;}\n.c-dropdown-row-text,\n.c-dropdown-option-text{flex:1 1 auto; min-width:0; display:flex; flex-direction:column; gap:var(--spacing-2);}\n.c-dropdown-row-text .c-dropdown-row-label,\n.c-dropdown-option-text .c-dropdown-option-label{overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}\n/* font-weight is declared here, not inherited, on purpose: .c-dropdown-option\n   is a <label>, and Input Field's own `.c-field label` rule sets label1/700\n   on every <label> inside a field. A panel rendered standalone in a gallery\n   card looks correct without this; the same panel inside a real trigger\n   renders its descriptions bold. Measured, not theorised. */\n.c-dropdown-row-desc,\n.c-dropdown-option-desc{font-family:var(--font-primary); font-size:var(--text-caption-size); line-height:var(--text-caption-lh); font-weight:var(--text-caption-weight); color:var(--color-neutral-5); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}\n.c-dropdown-row-meta,\n.c-dropdown-option-meta{flex:none; font-family:var(--font-primary); font-size:var(--text-caption-size); line-height:var(--text-caption-lh); font-weight:var(--text-caption-weight); color:var(--color-neutral-5);}\n.c-dropdown-row.disabled .c-dropdown-row-desc,\n.c-dropdown-row.disabled .c-dropdown-row-meta,\n.c-dropdown-option.disabled .c-dropdown-option-desc,\n.c-dropdown-option.disabled .c-dropdown-option-meta{color:var(--color-neutral-4);}\n\n/* Dropdown Option \u2014 description line (.has-desc). The slots themselves are\n   above; this is only the two-line row's own alignment. Checkbox's 2px\n   nudge is tuned for .c-choice, where the box sits beside a label that can\n   run to several lines and has to align to the first of them; a Dropdown\n   Option row is centred, so that nudge just pushes the box 1-2px low \u2014\n   invisible on a 34px row, visible on a 52px one. Reset here rather than\n   in Checkbox, which isn't wrong for its own component. */\n.c-dropdown-option .c-checkbox-box{margin-top:0;}\n/* A description makes the row two lines, and the leading media, the check,\n   the checkbox and the meta all stay optically on the LABEL rather than\n   floating between the two lines, which is where align-items:center would\n   put them. The avatar is the exception \u2014 at 24px it's taller than the\n   label's own line box, so it centres on the pair instead. */\n.c-dropdown-row.has-desc,\n.c-dropdown-option.has-desc{align-items:flex-start;}\n.c-dropdown-row.has-desc > .c-dropdown-row-media,\n.c-dropdown-row.has-desc > .c-dropdown-row-check,\n.c-dropdown-row.has-desc > .c-dropdown-row-meta,\n.c-dropdown-option.has-desc > .c-dropdown-option-media,\n.c-dropdown-option.has-desc > .c-dropdown-option-meta,\n.c-dropdown-option.has-desc > .c-checkbox-box{margin-top:1px;}\n.c-dropdown-row.has-desc > .c-dropdown-row-media.is-avatar,\n.c-dropdown-option.has-desc > .c-dropdown-option-media.is-avatar{margin-top:0;}\n\n/* Panel \u2014 Empty state, both variants. Empty State's own Search/Filter-level\n   variant already names \"autocomplete dropdown\" as one of its cases, so\n   this is that variant compressed to popover scale, not a second\n   empty-state family. Multiple select's footer stays rendered alongside it:\n   Clear and Done are still valid actions on a selection the filter is\n   merely hiding. */\n.c-dropdown-empty{display:flex; flex-direction:column; align-items:center; text-align:center; gap:var(--spacing-4); padding:var(--spacing-24) var(--spacing-16);}\n.c-dropdown-empty > i{font-size:var(--icon-md); color:var(--color-neutral-4);}\n.c-dropdown-empty-title{font-family:var(--font-primary); font-size:var(--text-body2-size); font-weight:700; color:var(--color-neutral-9);}\n.c-dropdown-empty-hint{font-family:var(--font-primary); font-size:var(--text-caption-size); line-height:var(--text-caption-lh); color:var(--color-neutral-5);}\n\n/* Panel \u2014 Loading state, both variants. No rule of its own on purpose:\n   Search input's .c-search-input-loading / .c-search-input-spinner is\n   reused verbatim in the markup rather than copied into a second, drifting\n   recipe. See DESIGN-SYSTEM.md's own note on the naming. */\n\n/* Searchable (.is-searchable), both variants. The trigger's own input\n   becomes genuinely editable rather than a display surface, so the caret\n   has to come back: .c-dropdown-input / .c-dropdown-multi-input both set\n   caret-color:transparent so a readonly box doesn't look typeable, which\n   silently defeated Multiple select's Searchable Behaviour \u2014 it dropped\n   `readonly` but nothing restored the cursor. */\n.c-dropdown-field.is-searchable .input-wrap,\n.c-dropdown-multi-field.is-searchable .input-wrap{cursor:text;}\n.c-dropdown-field.is-searchable .c-dropdown-input,\n.c-dropdown-multi-field.is-searchable .c-dropdown-multi-input{caret-color:auto; cursor:text;}\n\n/* Panel \u2014 Drop-up (.is-above). Set by the same runtime available-space\n   check Filters' own panel already documents, never by a breakpoint. In a\n   real implementation the panel is positioned against the trigger; in this\n   file both panels sit in normal flow inside .c-field's column flexbox, so\n   order:-1 is what moves one above its trigger. Note the rendered gap is\n   spacing-8 plus .c-field's own spacing-4 gap in BOTH directions, so\n   flipping never changes the distance. */\n.c-dropdown-panel.is-above,";

