// Multiple select: copied verbatim from collabrium-dls/components.css lines 4072–4190, for side-by-side comparison only.
export const legacyDropdownMultiCss = "/* Dropdown \u2014 Multiple select (designed not transcribed \u2014 renamed from\n   the standalone MultiSelect component; every property value below is\n   unchanged from that component, only the .c-ms* class prefix moved to\n   .c-dropdown-multi* so it reads as this component's other variant.\n   Supersedes an earlier single-select DropdownMenuWithSelection draft\n   on this same file \u2014 replaced per explicit user direction.\n   Trigger default matches Button Secondary exactly (Neutral-1 fill,\n   1px Neutral-3 border, shadow-1, radius-md, md size). Has-Selection's\n   border swaps to 1px Obsidian, the same \"holds a value\" recipe\n   Filters' own Filter trigger \u2014 active state uses. Has selection shows\n   one Badge-Neutral chip per selected option's label (capped at 2,\n   then a \"+N\" overflow chip) instead of the placeholder, built on\n   Badge's real box model (22px, spacing-8 padding, radius-pill,\n   caption/700, nowrap, 1px border) rather than an ad-hoc chip \u2014 and\n   stays shown while open too, so the user can see what's active while\n   browsing the checklist. Each visible chip has its own 14px \u00d7 to\n   remove just that option; the overflow \"+N\" chip has no \u00d7 since it\n   doesn't represent one single, removable option. Open is 2px Obsidian\n   with padding reduced 1px/side to compensate, the same\n   swap-and-compensate pattern Input field's focus state uses. Dropdown\n   panel reuses Filters'/Date picker's popover convention (radius-md,\n   1px Neutral-3 border, shadow-3). Group labels reuse SidebarNav's own\n   Section label recipe (caption/700/tracking-eyebrow/uppercase/\n   Neutral-5), --font-primary same as every other piece of text in the\n   component. Checkbox rows reuse this system's own Checkbox component spec\n   exactly (18\u00d718px, 6px radius, Obsidian border+fill when checked).\n   Footer reuses Button's Ghost/Primary variants at sm size with\n   Modal footer's divider convention. */\n/* Dropdown \u2014 Multiple select trigger (count-based, replaces the former\n   chip-based one). The box itself is Input Field's own container \u2014\n   .c-field/.input-wrap/.icon-trailing/.c-field-error/:disabled below\n   are all reused verbatim, unmodified; nothing here duplicates that\n   recipe. .c-dropdown-multi-field only adds a Style axis Input Field\n   doesn't have (scoped to this class so bare .c-field \u2014 Input field,\n   Textarea, Password field, Search input \u2014 is untouched), plus the\n   dropdown-specific chevron/panel/open/filled mechanics. The value now\n   reads \"N selected\" as the input's own value/placeholder text, not a\n   row of removable chips. */\n.c-dropdown-multi-field .input-wrap{cursor:pointer;}\n.c-dropdown-multi-input{cursor:pointer; caret-color:transparent;}\n.c-dropdown-multi-input::placeholder{color:var(--color-neutral-5);}\n.c-dropdown-multi-chevron{transition:transform var(--duration-fast) var(--ease-standard);}\n\n/* Style \u2014 Outlined is Input Field's own default recipe above (no\n   modifier class). Border stays 1px at rest, colour only, in every\n   Style \u2014 the same compensation-free trick Single select's own Style\n   axis uses, so Open's 1px\u21922px Obsidian swap below needs no per-style\n   exception. */\n.c-dropdown-multi-field:hover input, .c-dropdown-multi-field.hover input{background:var(--color-neutral-2);}\n.c-dropdown-multi-field.style-borderless input{background:transparent; border-color:transparent;}\n.c-dropdown-multi-field.style-borderless:hover input, .c-dropdown-multi-field.style-borderless.hover input{background:var(--color-neutral-2);}\n/* Disabled flattens both Styles to Input Field's own muted look\n   (Neutral-2 fill, Neutral-5 text, from .c-field input:disabled) \u2014\n   same explicit override precedent Single select's Style axis uses,\n   needed since .style-borderless's background:transparent would\n   otherwise tie in specificity and win by source order alone. */\n.c-dropdown-multi-field.style-borderless input:disabled{background:var(--color-neutral-2); border-color:transparent;}\n/* Error must win over Style too \u2014 .style-borderless's\n   border-color:transparent above outranks the existing, lower-\n   specificity .c-field-error rule on specificity alone, regardless of\n   which is declared later, so it needs an equally explicit override. */\n.c-dropdown-multi-field.style-borderless.c-field-error input{border-color:var(--color-red);}\n\n/* States \u2014 layer on top of whichever Style is active above. Real\n   :focus (Input Field's own swap, inherited free) already covers the\n   trigger being tabbed to before the panel is triggered \u2014 .open below\n   is a demo-only mirror of that same recipe, plus the panel itself. */\n.c-dropdown-multi-field.open input{border:2px solid var(--color-obsidian); padding:0 11px;}\n.c-dropdown-multi-field.open .c-dropdown-multi-chevron{transform:rotate(180deg);}\n.c-dropdown-multi-field.filled input{border-color:var(--color-obsidian);}\n.c-dropdown-multi-field.read-only .input-wrap{pointer-events:none;}\n.c-dropdown-multi-field.read-only .icon-trailing{display:none;}\n/* Borderless stays borderless through every State \u2014 Open and Filled's\n   border-color swap above is deliberately suppressed here so this\n   Style never shows a solid border, the one thing \"Borderless\" is\n   supposed to guarantee. Only overrides border-color (not the whole\n   border shorthand), so the width/padding compensation math above\n   still runs identically in every Style \u2014 there's just nothing visible\n   riding on it in this one. */\n.c-dropdown-multi-field.style-borderless.open input, .c-dropdown-multi-field.style-borderless.filled input{border-color:transparent;}\n\n/* Panel \u2014 width:100% of the same .c-field parent the trigger fills, so\n   it always matches the trigger's rendered width, same guarantee as\n   Single select's own panel. */\n.c-dropdown-multi-panel{position:static; margin-top:var(--spacing-8); width:100%; background:var(--color-neutral-1); border:1px solid var(--color-neutral-3); border-radius:var(--radius-md); box-shadow:var(--shadow-3); overflow:hidden;}\n.c-dropdown-multi-list{max-height:320px; overflow-y:auto; padding:var(--spacing-8) 0;}\n.c-dropdown-multi-divider{height:1px; background:var(--color-neutral-3); margin:var(--spacing-8) 0;}\n.c-dropdown-multi-group{padding:var(--spacing-4) var(--spacing-12); font-family:var(--font-primary); font-size:var(--text-caption-size); font-weight:700; letter-spacing:var(--tracking-eyebrow); text-transform:uppercase; color:var(--color-neutral-5);}\n\n/* Dropdown Option \u2014 the checkbox row sub-component inside Multiple\n   select's panel, including the pinned Select All row (With Select\n   All behaviour only). Reuses this system's own Checkbox glyph\n   (.c-checkbox-box/.on + ph-check/ph-minus, from the Checkbox\n   component) verbatim rather than a second, ad-hoc checkbox recipe \u2014\n   only the row's own padding/hover chrome is new, since Checkbox\n   itself (a compact form control, not a list row) never needed it. */\n/* position:relative anchors the hidden native input \u2014 see .c-choice. */\n.c-dropdown-option{position:relative; display:flex; align-items:center; gap:var(--spacing-8); padding:var(--spacing-8) var(--spacing-12); cursor:pointer;}\n.c-dropdown-option input{position:absolute; opacity:0; width:0; height:0;}\n.c-dropdown-option:hover, .c-dropdown-option.hover{background:var(--color-neutral-2);}\n.c-dropdown-option.disabled{color:var(--color-neutral-4); cursor:not-allowed; pointer-events:none;}\n.c-dropdown-option.disabled .c-checkbox-box{border-color:var(--color-neutral-3); background:var(--color-neutral-2);}\n.c-dropdown-option-label{font-family:var(--font-primary); font-size:var(--text-body2-size); font-weight:var(--text-body2-weight); color:var(--color-neutral-9);}\n.c-dropdown-option.disabled .c-dropdown-option-label{color:var(--color-neutral-4);}\n.c-dropdown-option.select-all .c-dropdown-option-label{font-weight:700;}\n\n.c-dropdown-multi-footer{display:flex; justify-content:space-between; gap:var(--spacing-8); padding:var(--spacing-12); border-top:1px solid var(--color-neutral-3);}\n.c-dropdown-multi-footer button{height:var(--control-height-sm); padding:0 var(--spacing-12); border:none; border-radius:var(--radius-sm); font-family:var(--font-primary); font-size:var(--text-label2-size); font-weight:var(--text-label2-weight); cursor:pointer;}\n.c-dropdown-multi-footer .clear{background:transparent; color:var(--color-neutral-9);}\n.c-dropdown-multi-footer .clear:hover{background:var(--color-neutral-2);}\n.c-dropdown-multi-footer .done{background:var(--color-obsidian); color:var(--color-neutral-1);}\n.c-dropdown-multi-footer .done:hover{background:var(--color-neutral-8);}\n/* Disabled footer buttons \u2014 the Loading state renders the footer inert,\n   and the native :disabled attribute alone changes nothing here, so an\n   inert Clear/Done looked identical to a live one. Opacity + cursor,\n   matching .c-choice.disabled's own treatment rather than a new one. */\n.c-dropdown-multi-footer button:disabled{opacity:.5; cursor:not-allowed;}\n.c-dropdown-multi-footer .clear:disabled:hover{background:transparent;}\n.c-dropdown-multi-footer .done:disabled:hover{background:var(--color-obsidian);}";

